/**
 * How customers pay you. Use your gateway's test keys until you have placed a full practice order, then swap in the live ones.
 *
 * This interface was referenced by `Config`'s JSON-Schema
 * via the `definition` "payment-settings".
 */
export interface PaymentSetting {
  id: number;
  /**
   * Card payments through Stripe. All four values come from the Developers area of your Stripe dashboard.
   */
  stripe?: {
    enabled?: boolean | null;
    /**
     * While this is on, no real money moves. Make sure the keys below are the matching test ones - mixing test and live keys causes failures that are hard to diagnose.
     */
    testMode?: boolean | null;
    /**
     * Starts pk_test_ or pk_live_. This one is public - it is used in the checkout page - but it is stored in the database like the rest.
     */
    publishableKey?: string | null;
    /**
     * Starts sk_test_ or sk_live_. Stored encrypted at rest, visible only to admins. Treat it like your bank password and rotate it in Stripe if it is ever exposed.
     */
    secretKey?: string | null;
    /**
     * Starts whsec_. Stripe uses it to prove that order updates really came from Stripe. Stored encrypted at rest, visible only to admins.
     */
    webhookSigningSecret?: string | null;
  };
  /**
   * PayPal payments. Credentials come from your PayPal developer dashboard.
   */
  paypal?: {
    enabled?: boolean | null;
    /**
     * Sandbox is for practice orders. Switch to live only once you have tested, and use the matching credentials.
     */
    environment?: ('sandbox' | 'live') | null;
    /**
     * Your PayPal app client ID. Must match the environment selected above.
     */
    clientId?: string | null;
    /**
     * Your PayPal app secret. Stored encrypted at rest, visible only to admins - rotate it in PayPal if it is ever exposed.
     */
    clientSecret?: string | null;
    /**
     * Offer PayPal's pay-in-instalments option at checkout. Availability depends on your account and the customer's country.
     */
    allowPayPalLater?: boolean | null;
  };
  /**
   * Settings that apply no matter which gateway takes the payment.
   */
  general?: {
    /**
     * The currency prices are charged in.
     */
    currency?: ('AUD' | 'USD' | 'GBP' | 'EUR' | 'NZD') | null;
    /**
     * Automatic takes the money at checkout. Manual only reserves it, and you confirm the charge later - useful for made-to-order items, but reservations expire after a few days.
     */
    captureMethod?: ('automatic' | 'manual') | null;
    /**
     * What customers see on their bank statement. Make it recognisably your shop - an unfamiliar name is a common cause of chargebacks. Usually limited to 22 characters.
     */
    statementDescriptor?: string | null;
  };
  updatedAt?: string | null;
  createdAt?: string | null;
}
/**
 * Defaults for every form on your site. Any individual form can override these on its own settings.
 *
 * This interface was referenced by `Config`'s JSON-Schema
 * via the `definition` "form-settings".
 */
export interface FormSetting {
  id: number;
  /**
   * What happens to an entry once someone presses send.
   */
  submissions?: {
    /**
     * Keep a copy in the admin area. Worth leaving on - if a notification email goes astray, this is the only record of the enquiry.
     */
    storeSubmissions?: boolean | null;
    /**
     * How long stored entries are kept before being deleted. Entries usually hold personal details, so keep them only as long as you genuinely need them. Set to 0 to keep them indefinitely.
     */
    retentionDays?: number | null;
    /**
     * Email someone whenever a form is submitted.
     */
    sendAdminNotification?: boolean | null;
    /**
     * Who gets that email. Separate several addresses with commas. Delivery uses whichever provider is set in Email settings.
     */
    notificationRecipients?: string | null;
  };
  /**
   * Filters out automated submissions. The first two are invisible to real visitors and cost nothing - start with those.
   */
  spam?: {
    /**
     * Adds a hidden field that people never see but bots tend to fill in. Anything that completes it is discarded.
     */
    honeypot?: boolean | null;
    /**
     * Reject submissions sent faster than a person could type. Three seconds is safe; much higher starts catching genuinely quick visitors.
     */
    minimumFillTimeSeconds?: number | null;
    /**
     * Turn on Cloudflare Turnstile, a challenge that is usually invisible to real visitors. Use it if spam is still getting through - it adds a Cloudflare script to every page that has a form.
     */
    turnstile?: boolean | null;
    /**
     * From the Turnstile section of your Cloudflare dashboard. This one is public - it appears in the form itself.
     */
    turnstileSiteKey?: string | null;
    /**
     * The matching secret key from Cloudflare. Stored encrypted at rest, visible only to admins - rotate it in Cloudflare if it is ever exposed.
     */
    turnstileSecretKey?: string | null;
  };
  /**
   * The wording a new form starts with. Every form can change its own.
   */
  defaults?: {
    /**
     * The text on the send button. Something specific like "Send enquiry" reads better than "Submit".
     */
    submitButtonLabel?: string | null;
    /**
     * Shown after a successful submission. Say what happens next and roughly when.
     */
    successMessage?: string | null;
    /**
     * Shown when a submission fails. Give people another way to reach you here - an email address or phone number - so a broken form does not cost you the enquiry.
     */
    errorMessage?: string | null;
  };
  updatedAt?: string | null;
  createdAt?: string | null;
}
